// TH15 v1.00b Stage 7 (Extra) BossCard5 異界「地獄のノンイデアル弾幕」
// Source: st07bs.ecl.txt:1966-2094 (BossCard5 and its two dependencies).
// Source entry maps to card frame OPENING_BUFFER; timerReset at source+4,
// setInterrupt timeout 4800 -> card 120+4+4800 = 4924.
const TIME_LIMIT: int = 4924;
const OPENING_BUFFER: int = 120;

// TH15 type 25 / 16, copied from transcribe/th15/touhou-bullets.ecl.
const TH15_FIREBALL_RED: int = 752;
const TH15_STAR_R: int = 608;

// Source BossCard5_at EX records 2/3 + GOTO record 4 (jump back to index 2):
// ANGLE_ACCEL a=60, r=0, s=%F1/%F2 alternating forever.  Source s is rad/frame;
// converted to BAM/frame: 0.024435 -> 255, 0.034907 -> 364.  ANGLE_ACCEL's
// r=0 leaves speed unchanged, matching set_ang_vel's POLAR rotation only.
xformdef CARD5_SPIN(w1: angle, w2: angle) {
again:
    set_ang_vel(w1);
    wait(60);
    set_ang_vel(w2);
    wait(60);
    loop(again, 0);
}

// BossCard5_at2: every 40 frames, if the player is inside 128px, emit a
// 32-way STAR_R ring (type 16, color 6) at speed 1.5 with a random base angle.
// etAim=3 fixed ring; RANDRAD base is uniform over the circle.
async sub at2() {
    loop {
        if dist($player_x - $self_x, $player_y - $self_y) < 128fx {
            sh_reset(1);
            sh_sprite(1, TH15_STAR_R, 6);
            sh_ring(1, 1);
            sh_aim(1, 0);
            sh_count(1, 32, 1);
            sh_angle(1, rand(65536) as angle, 0deg);
            sh_speed(1, 1.5fx, 0fx);
            // ANIM a=1: source position -= 4 * velocity = 6px along each angle.
            sh_dist(1, -6fx);
            sh_fire(1);
        }
        wait(40);
    }
}

// BossCard5_at.  %A starts at pi/2 and is kept in milli-BAM so the 100x3
// accumulations do not drift; source 1.5deg*F0 / 45deg*F0 become inner/outer.
// Source etCount(6,1), etAim(1) fixed fan with 45deg path step, speed 2,
// etDist 64 and ANIM a=1 retreat 4*speed=8 -> net 56px along each angle.
sub fan(inner_mb: int, outer_mb: int) {
    var a_mb: int = 16384000; // 90deg in milli-BAM
    sh_reset(0);
    sh_sprite(0, TH15_FIREBALL_RED, 0);
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_count(0, 6, 1);
    sh_speed(0, 2fx, 0fx);
    sh_dist(0, 56fx);
    for b in 0..100 {
        for d in 0..3 {
            sh_angle(0, (a_mb / 1000) as angle, 45deg);
            sh_fire(0);
            a_mb = a_mb - inner_mb;
            wait(2);
        }
        a_mb = a_mb + outer_mb;
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Source 2001: movePosTime(60,4,0,128).  Boss already starts at (0,128).
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(94); // source time 94 = first BossCard5_at / at2 start
    spawn at2();
    // Source $C=1000 loop of two BossCard5_at calls; the 4800-frame timer
    // ends long before the 1000th pair.  F0=1.29 / -1.7 per half.
    for round in 0..1000 {
        fan(352256, 10567680);
        wait(90);
        fan(-464213, -13926400);
        wait(90);
    }
    loop { wait(1000); }
}

async sub boss_main() {
    set_invuln(65535);
    // Source Boss entry / card setup: hitbox 48x48 -> r=24, hurtbox 40x40 -> r=20.
    set_hitbox(24fx);
    set_hurtbox(20fx);
    // Source entry order: etCancel(640), timerReset, killAllAsync, enmKillAll,
    // etCancel(640) again (timeout==0 branch).  Both clears are empty here.
    clear_bullets();
    // Source enmKillAll; target excludes the caller.  killAllAsync has no
    // separate call: no async task exists before pattern/at2 are spawned.
    kill_all_enemies(KILL_SILENT);
    clear_bullets();
    // Source timerReset + setInterrupt(4800) + spellEx(113,4800,500000).
    spell_begin(0, 113, pattern, TIME_LIMIT, 500000, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss_main);
    loop { wait(600); }
}
